 body=<!--
  MessMate Admin Dashboard (dashboard.html)
  -----------------------------------------
  This Jinja2 template renders the stakeholder dashboard. It displays
  dynamic variables passed from the Flask backend, including Today's Average
  Stat Cards, historical feedback trends, and a scrollable list of student
  suggestions. It also loads Chart.js and static/dashboard.js to render the graphs.
-->

<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>MessMate — Admin Dashboard 📊</title>

  <!-- Shared mobile-first styles -->
  <link rel="stylesheet" href="/static/style.css">

  <!-- Add Chart.js via CDN -->
  <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>

  <!-- Dashboard specific styles -->
  <style>
    body {
      background-color: #f4f7f6;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      margin: 0;
      padding: 20px;
    }

    .dashboard-container {
      max-width: 1200px;
      margin: 0 auto;
    }

    .dashboard-header {
      margin-bottom: 30px;
      color: #1F4E79;
    }

    .dashboard-header h1 {
      margin: 0 0 10px 0;
    }

    /* Stat Cards Section */
    .stat-cards {
      display: flex;
      gap: 20px;
      margin-bottom: 30px;
      flex-wrap: wrap;
    }

    .stat-card {
      flex: 1;
      min-width: 250px;
      background: white;
      border-radius: 12px;
      padding: 24px;
      box-shadow: 0 4px 6px rgba(0,0,0,0.05);
      text-align: center;
      border: 1px solid #e0e0e0;
    }

    .stat-card h3 {
      margin: 0 0 10px 0;
      font-size: 16px;
      color: #666;
      font-weight: 500;
    }

    .stat-value {
      font-size: 40px;
      font-weight: 700;
      margin: 0;
      color: #333;
    }

    /* Dynamic Colors for Average Score Card */
    .score-red {
      background-color: #FFEBEE;
      color: #B71C1C;
      border: 1px solid #ffcdd2;
    }

    .score-amber {
      background-color: #FFF3E0;
      color: #BF5700;
      border: 1px solid #ffe0b2;
    }

    .score-green {
      background-color: #E8F5E9;
      color: #1E6B3C;
      border: 1px solid #c8e6c9;
    }

    .score-value {
      color: inherit;
    }

    /* Charts Section */
    .charts-row {
      display: flex;
      gap: 20px;
      margin-bottom: 30px;
      flex-wrap: wrap;
    }

    .chart-container {
      flex: 1;
      min-width: 400px;
      background: white;
      border-radius: 12px;
      padding: 24px;
      box-shadow: 0 4px 6px rgba(0,0,0,0.05);
      border: 1px solid #e0e0e0;
    }

    .chart-container h3 {
      margin: 0 0 20px 0;
      color: #1F4E79;
    }

    .canvas-wrapper {
      position: relative;
      height: 300px;
      width: 100%;
    }

    /* Suggestions Section */
    .suggestions-container {
      background: white;
      border-radius: 12px;
      padding: 24px;
      box-shadow: 0 4px 6px rgba(0,0,0,0.05);
      border: 1px solid #e0e0e0;
      margin-bottom: 40px;
    }

    .suggestions-container h3 {
      margin: 0 0 20px 0;
      color: #1F4E79;
    }

    .suggestions-list {
      max-height: 400px;
      overflow-y: auto;
      padding-right: 10px;
    }

    .suggestion-item {
      padding: 15px;
      border-bottom: 1px solid #f0f0f0;
    }

    .suggestion-item:last-child {
      border-bottom: none;
    }

    .suggestion-text {
      margin: 0 0 5px 0;
      font-size: 16px;
      line-height: 1.4;
    }

    .suggestion-time {
      font-size: 12px;
      color: #888;
      margin: 0;
    }

    .empty-state {
      padding: 20px;
      text-align: center;
      color: #888;
      font-style: italic;
    }

    @media (max-width: 768px) {
      .stat-card {
        min-width: 100%;
      }
      .chart-container {
        min-width: 100%;
      }
    }
  </style>
</head>
<body>

<div class="dashboard-container">

  <div class="dashboard-header">
    <h1>MessMate Admin Dashboard 🍱</h1>
    <p>Live student feedback analytics</p>
  </div>

  <!-- SECTION 1 — TOP STAT CARDS -->
  <div class="stat-cards">

    <!-- Card A: Today's Average -->







    <div class="stat-card score-green">
      <h3>Today's Average</h3>
      <p class="stat-value score-value">

          4.0

      </p>
    </div>

    <!-- Card B: Responses Today -->
    <div class="stat-card">
      <h3>Responses Today</h3>
      <p class="stat-value">1</p>
    </div>

    <!-- Card C: Today's Date -->
    <div class="stat-card">
      <h3>Today's Date</h3>
      <p class="stat-value" style="font-size: 24px; padding-top: 10px;">Sunday, 19 April 2026</p>
    </div>

  </div>

  <!-- CHARTS ROW -->
  <div class="charts-row">

    <!-- SECTION 2 — OVERALL TREND CHART -->
    <div class="chart-container">
      <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px;">
        <h3 id="trendChartTitle" style="margin-bottom: 0;">7-Day Overall Trend</h3>
        <div class="toggle-group">
          <button id="btn7Days" class="toggle-btn active">7 Days</button>
          <button id="btn30Days" class="toggle-btn">1 Month</button>
        </div>
      </div>
      <div class="canvas-wrapper">
        <canvas id="trendChart"></canvas>
      </div>
    </div>

    <!-- SECTION 3 — PER-ITEM SCORES CHART -->
    <div class="chart-container">
      <h3>Today's Item Scores</h3>
      <div class="canvas-wrapper">
        <canvas id="itemChart"></canvas>
      </div>
    </div>

  </div>

  <!-- SECTION 4 — SUGGESTED DISHES LIST -->
  <div class="suggestions-container">
    <h3>💡 Student Suggestions</h3>

    <div class="suggestions-list">


        <div class="suggestion-item">
