    /* Stat Cards Section */
    .stat-cards {
      display: flex;
      gap: 20px;
      margin-bottom: 30px;
      flex-wrap: wrap;
    }

    .stat-card {
      flex: 1;
      min-width: 250px;
      background: white;
      border-radius: 12px;
      padding: 24px;
      box-shadow: 0 4px 6px rgba(0,0,0,0.05);
      text-align: center;
      border: 1px solid #e0e0e0;
    }

    .stat-card h3 {
      margin: 0 0 10px 0;
      font-size: 16px;
      color: #666;
      font-weight: 500;
    }

    .stat-value {
      font-size: 40px;
      font-weight: 700;
      margin: 0;
      color: #333;
    }

    /* Dynamic Colors for Average Score Card */
    .score-red {
      background-color: #FFEBEE;
      color: #B71C1C;
      border: 1px solid #ffcdd2;
    }

    .score-amber {
      background-color: #FFF3E0;
      color: #BF5700;
      border: 1px solid #ffe0b2;
    }

    .score-green {
      background-color: #E8F5E9;
      color: #1E6B3C;
      border: 1px solid #c8e6c9;
    }

    .score-value {
      color: inherit;
    }

    /* Charts Section */
    .charts-row {
      display: flex;
      gap: 20px;
      margin-bottom: 30px;
      flex-wrap: wrap;
    }

    .chart-container {
      flex: 1;
      min-width: 400px;
      background: white;
      border-radius: 12px;
      padding: 24px;
      box-shadow: 0 4px 6px rgba(0,0,0,0.05);
      border: 1px solid #e0e0e0;
    }

    .chart-container h3 {
      margin: 0 0 20px 0;
      color: #1F4E79;
    }

    .canvas-wrapper {
      position: relative;
      height: 300px;
      width: 100%;
    }

    /* Suggestions Section */
    .suggestions-container {
      background: white;
      border-radius: 12px;
      padding: 24px;
      box-shadow: 0 4px 6px rgba(0,0,0,0.05);
      border: 1px solid #e0e0e0;
      margin-bottom: 40px;
    }

    .suggestions-container h3 {
      margin: 0 0 20px 0;
      color: #1F4E79;
    }

    .suggestions-list {
      max-height: 400px;
      overflow-y: auto;
      padding-right: 10px;
    }

    .suggestion-item {
      padding: 15px;
      border-bottom: 1px solid #f0f0f0;
    }

    .suggestion-item:last-child {
      border-bottom: none;
    }

    .suggestion-text {
      margin: 0 0 5px 0;
      font-size: 16px;
      line-height: 1.4;
    }

    .suggestion-time {
      font-size: 12px;
      color: #888;
      margin: 0;
    }

    .empty-state {
      padding: 20px;
      text-align: center;
      color: #888;
      font-style: italic;
    }

    @media (max-width: 768px) {
      .stat-card {
        min-width: 100%;
      }
      .chart-container {
        min-width: 100%;
      }
    }
  </style>
